{
  "ok": false,
  "name": "place_table",
  "error": {
    "type": "invalid_params",
    "message": "Additional properties are not allowed ('layers' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "position": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "top-left corner; table grows downward"
        },
        "title": {
          "type": "string"
        },
        "columns": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "properties": {
              "header": {
                "type": "string"
              },
              "width": {
                "type": "number",
                "exclusiveMinimum": 0
              }
            },
            "required": [
              "header",
              "width"
            ],
            "additionalProperties": false
          }
        },
        "rows": {
          "type": "array",
          "items": {
            "type": "array",
            "items": {
              "type": [
                "string",
                "number"
              ]
            }
          }
        },
        "text_height": {
          "type": "number",
          "exclusiveMinimum": 0
        },
        "style": {
          "type": "string",
          "minLength": 1
        }
      },
      "required": [
        "space",
        "position",
        "columns",
        "rows"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "SH-004",
      "position": [
        26.0,
        8.0
      ],
      "title": "CURVE DATA",
      "columns": [
        {
          "header": "CURVE",
